rt re\n\n# Find all lines that look like year/month data in the debt table\n# These should be in the format: | YEAR | TOTAL | PUBLIC_DEBT | AGENCY | ...\nlines = content.split('\\n')\nfor i, line in enumerate(lines):\n    # Look for lines with 10 fields (the FD-1 table format)\n    if '|' in line:\n        parts = [p.strip() for p in line.split('|') if p.strip()]\n        # Check if first part is a year (4 digits) or year-month\n        if len(parts) >= 4:\n            first = parts[0]\n            # Check if it's a year pattern\n            if re.match(r'^\\d{4}$', first):\n                # Check if the second part is a large number (debt total)\n                if re.match(r'^\\d{3},\\d{3}$', parts[1]) or re.match(r'^\\d{6}$', parts[1]):\n                    print(f'Line {i}: {first} -> {parts[1]}')\n\" | head -30"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
